package com.bitedash.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {record ErrorResponse(LocalDateTime timestamp,int status,String error,String message){ } @ExceptionHandler(NotFoundException.class) ResponseEntity<ErrorResponse> notFound(NotFoundException e){return error(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler({BadRequestException.class,IllegalArgumentException.class}) ResponseEntity<ErrorResponse> bad(RuntimeException e){return error(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).findFirst().orElse("Invalid request");return error(HttpStatus.BAD_REQUEST,m);} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> general(Exception e){return error(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error");} private ResponseEntity<ErrorResponse> error(HttpStatus s,String m){return ResponseEntity.status(s).body(new ErrorResponse(LocalDateTime.now(),s.value(),s.getReasonPhrase(),m));}}
